import{t as e}from"./jsx-runtime-lw2jiZar.js";import{B as t,C as n,M as r,N as i,O as a,P as o,S as s,b as c,d as l,k as u,l as d,n as f,o as p,t as m,w as h}from"./shared-C5BCElVa.js";import{t as g}from"./git-fork-WIYO3FwZ.js";var _=e();function v({module:e}){return(0,_.jsxs)(i,{children:[(0,_.jsx)(r,{variant:`project`,chip:e??`Блок 12 · Проверяемая передача`,title:`Жизненный цикл одной задачи`,intro:`Проверим одну задачу в цепочке запросов: от создания до удаления, включая отказ без изменения данных.`,tags:[{icon:(0,_.jsx)(g,{size:14}),label:`одна история запросов`},{icon:(0,_.jsx)(t,{size:14}),label:`workflow-тест`}]}),(0,_.jsxs)(o,{number:`00`,title:`От отдельных проверок к одной истории`,children:[(0,_.jsx)(a,{children:`Отдельные API-тесты проверяют отдельные операции: создание возвращает 201, неверные данные дают 422, удаление возвращает 204. Клиент обычно отправляет цепочку запросов: создаёт задачу, берёт её id, меняет и удаляет. Проверим, что все запросы работают с одной задачей и её состоянием.`}),(0,_.jsx)(u,{variant:`connected`,items:[{title:`Точка старта`,description:`Из занятия 59 приходят карта проверок Planner, готовые HTTP-маршруты и fixtures api_service и api_client.`},{title:`Новый вопрос`,description:`Сохраняют ли запросы один id, состояние главной задачи и контрольную запись?`},{title:`Результат`,description:`Добавим один workflow-тест и повторим ту же историю в Postman. Эти результаты передадим занятию 60.`}]}),(0,_.jsx)(`p`,{children:`Маршруты, сервис и fixtures уже готовы. CRUD повторно не пишем и код приложения не меняем. Занятие 59 подготовило карту отдельных проверок; теперь свяжем эти проверки в одну историю. Само описание не доказывает результат: его подтвердят тест и запросы.`}),(0,_.jsx)(`p`,{children:`Отдельные тесты похожи на проверку декораций, света и звука по отдельности. Workflow-тест проверяет весь прогон спектакля и порядок событий. Проверки деталей он не заменяет.`})]}),(0,_.jsxs)(o,{number:`01`,title:`Чем одна последовательность отличается от набора случаев`,children:[(0,_.jsx)(a,{children:`Отдельный API-тест быстро показывает, какая операция сломалась. Но тесты POST, PUT, PATCH и DELETE могут работать с разными задачами. Они не доказывают, что id из POST подходит для следующих запросов или что PATCH видит результат PUT.`}),(0,_.jsx)(`p`,{children:`Workflow-тест выполняет одну историю в одной функции. Он сохраняет id из ответа POST и использует его в GET, PUT, PATCH и DELETE. Каждый запрос получает состояние после предыдущего. Иначе тест может обращаться к разным задачам.`}),(0,_.jsx)(`p`,{children:`Не нужно проверять весь API в одном сценарии. Выберите одну важную цепочку, а отдельные правила оставьте существующим тестам. Если цепочка ломается, отдельные проверки помогут найти проблемную операцию. Если отдельные операции проходят, проверьте передачу id, состояния и порядок запросов.`}),(0,_.jsx)(c,{question:`Какой вывод доказывает workflow-тест, но не следует автоматически из четырёх независимых тестов?`,options:[`Что несколько запросов используют одну созданную задачу в заданном порядке`,`Что каждый маршрут имеет отдельную функцию Python`,`Что все возможные входы API перебраны`],correctIndex:0,explanation:`Одна функция связывает ответы и состояние запросов. Она не проверяет все варианты входа и не заменяет отдельные тесты правил.`}),(0,_.jsx)(`p`,{children:`Тест может пройти успешно, даже если один запрос получил ожидаемый отказ 422. После отказа проверьте, что данные не изменились и следующий правильный запрос работает.`})]}),(0,_.jsxs)(o,{number:`02`,title:`Одно тестовое состояние на все запросы`,children:[(0,_.jsx)(a,{children:`Все запросы одной истории должны использовать один сервис и один временный файл. Готовые fixtures api_service и api_client делают это для каждой тестовой функции. Сервис хранит данные в JsonStorage внутри tmp_path; клиент подключает его через app.state.planner. После закрытия TestClient fixture возвращает прежний сервис.`}),(0,_.jsx)(`p`,{children:`Function scope означает: каждая тестовая функция получает отдельный сервис. Внутри одной функции сервис не пересоздаётся перед каждым запросом. Поэтому следующий GET видит задачу после POST, а PUT меняет её же. В новом тесте будет новый временный файл. Дополнительная fixture и очистка после каждого запроса не нужны.`}),(0,_.jsxs)(m,{caption:`Один тест удерживает временное состояние между запросами`,children:[(0,_.jsxs)(p,{label:`Последовательность workflow-теста`,orientation:`vertical`,children:[(0,_.jsx)(d,{title:`Один запуск тестовой функции`,shape:`terminator`,children:(0,_.jsx)(`p`,{children:`api_client подключает временный api_service`})}),(0,_.jsx)(f,{label:`общий tmp_path`}),(0,_.jsx)(d,{title:`POST → GET → PUT → PATCH → DELETE`,children:(0,_.jsx)(`p`,{children:`Каждый следующий запрос видит предыдущий переход`})}),(0,_.jsx)(f,{label:`завершение fixture`}),(0,_.jsx)(d,{title:`Следующая функция`,children:(0,_.jsx)(`p`,{children:`Получает независимый сервис и свежий файл`})})]}),(0,_.jsx)(l,{label:`Граница данных`,items:[`одна функция`,`общая история`,`следующий тест изолирован`],activeIndex:1})]}),(0,_.jsx)(`p`,{children:`Каждый HTTP-запрос является отдельным сообщением. Пока открыт один TestClient, все сообщения используют одно FastAPI-приложение и один подключённый сервис. При закрытии клиента fixture возвращает прежний app.state.planner. Для такого теста Uvicorn запускать не нужно.`}),(0,_.jsx)(s,{statement:(0,_.jsx)(_.Fragment,{children:`Если два последовательных запроса сделаны через один api_client внутри функции, между ними можно ожидать общее состояние тестового сервиса.`}),isTrue:!0,explanation:`Да. Один api_service используется до конца функции. Следующая функция получит отдельное состояние.`})]}),(0,_.jsxs)(o,{number:`03`,title:`Связываем историю фактическими id`,children:[(0,_.jsx)(a,{children:`Создайте главную задачу и контрольную запись. Главную будем менять, контрольная должна остаться прежней. Сохраняйте id из каждого ответа POST: их выдаёт приложение. Не подставляйте число 1 и не берите номер строки из списка.`}),(0,_.jsx)(`p`,{children:`Контрольная задача помогает заметить случайное изменение соседа. После PUT мало проверить, что задач по-прежнему две: можно было изменить не ту задачу. Прочитайте главную по её id и отдельно проверьте, что поля контрольной задачи не изменились. Это как проверить номер посылки, а не только их общее количество.`}),(0,_.jsx)(`p`,{children:`Сначала GET должен вернуть главную задачу с теми же id, title, priority и is_done, что и ответ POST. Затем PUT заменяет поля и ставит is_done=true. Проверьте статус и тело PUT, прочитайте задачу ещё раз по тому же id и проверьте контрольную запись. Так мы подтвердим и ответ, и сохранённые данные.`}),(0,_.jsx)(n,{code:[`task_id = 1`,`response = api_client.get(f"/tasks/{task_id}")`,`assert response.status_code == 200`].join(`
`),question:`Какую ошибку может скрыть этот фрагмент, если настоящий id из POST оказался другим?`,options:[`Тест обращается к предположительному id вместо созданной задачи`,`GET не может возвращать JSON`,`Статус 200 запрещён для чтения`],correctIndex:0,explanation:`Связываем действия только значением из ответа POST. Так тест не зависит от стартового счётчика, порядка строк или содержимого базы.`,fix:[`created = api_client.post("/tasks", json=payload).json()`,`task_id = created["id"]`,`response = api_client.get(f"/tasks/{task_id}")`].join(`
`)}),(0,_.jsx)(`p`,{children:`Один id связывает все запросы с главной задачей. Повторный GET проверяет её состояние, а контрольная запись помогает заметить, если изменился сосед.`})]}),(0,_.jsxs)(o,{number:`04`,title:`Сравниваем ответ, сохранённое состояние и статистику`,children:[(0,_.jsx)(a,{children:`После каждого важного действия проверьте три вещи: ответ запроса, повторный GET и stats. Ответ показывает результат вызова, GET показывает сохранённое состояние задачи, а stats показывают общее число открытых и выполненных задач. Список и контрольная запись помогают заметить изменение соседа.`}),(0,_.jsx)(`p`,{children:`Обозначим исходные stats как N/O/D: total, open и done. После двух POST будет N+2/O+2/D. PUT главной задачи с is_done=true даст N+2/O+1/D+1. PATCH с is_done=false вернёт N+2/O+2/D. После удаления главной останется N+1/O+1/D. В Postman сравнивайте результат с исходными значениями: рабочий JSON может быть непустым.`}),(0,_.jsx)(`p`,{children:`Сверяйте stats до и после действия, а не с постоянными числами. После PATCH количество задач не меняется. После DELETE проверьте пустое тело 204 и GET 404 для главной задачи; контрольная должна по-прежнему читаться.`}),(0,_.jsx)(h,{prompt:`Соберите короткую последовательность доказательств для проверки PUT одной задачи. Между действиями остаётся один api_client.`,pieces:[{id:`put`,code:`PUT по id из POST`,note:`переход состояния`},{id:`get`,code:`GET той же записи`,note:`повторное чтение`},{id:`stats`,code:`GET /stats`,note:`агрегат`}],correctOrder:[`put`,`get`,`stats`],explanation:`Сначала выполните PUT, затем перечитайте эту задачу и сравните stats.`,title:`Соберите проверки перехода`,label:`СОБИРАЕМ ИСТОРИЮ`}),(0,_.jsx)(`p`,{children:`Эти проверки дополняют друг друга. Ответ подтверждает вызов, повторный GET показывает состояние задачи, а stats показывают общий итог. Контрольная запись помогает проверить, что сосед не изменился.`})]}),(0,_.jsxs)(o,{number:`05`,title:`Ожидаемый отказ не должен прерывать историю`,children:[(0,_.jsx)(a,{children:`После PUT задача выполнена. Теперь отправьте PATCH с priority=99. API должен вернуть 422. Одного статуса мало: он не показывает, изменились ли данные до отказа. Сохраните главную и контрольную задачи со stats до запроса, затем прочитайте их снова.`}),(0,_.jsx)(`p`,{children:`После 422 обе задачи и stats должны остаться прежними. Затем продолжите историю: отправьте PATCH с is_done=false. Проверьте, что задача снова открыта, а title и priority сохранились. Так тест проверит и отказ, и следующий успешный запрос.`}),(0,_.jsx)(`p`,{children:`Используйте известное правило API: priority=99 недопустим. Отправляйте PATCH на правильный id и проверяйте данные после 422. Иначе тест подтвердит только статус, но не сохранность состояния.`}),(0,_.jsx)(`p`,{children:`Это похоже на отклонённую оплату: отказ не должен менять корзину или соседний заказ. Сравните данные до и после отказа, затем продолжите правильным запросом.`})]}),(0,_.jsxs)(o,{number:`06`,title:`TestClient и Postman подтверждают разные границы`,children:[(0,_.jsx)(a,{children:`TestClient вызывает настоящее приложение внутри теста. Uvicorn для него запускать не нужно: fixture использует временный файл tmp_path. Postman отправляет запросы к запущенному серверу и его хранилищу. Так мы проверяем историю и автоматически, и вручную.`}),(0,_.jsx)(`p`,{children:`Из корня StudyHub запустите сервер командой python -m uvicorn app.api:app --reload. В Postman нажмите Import и добавьте postman/planner-api.postman_collection.json и postman/local.postman_environment.json. Выберите Local: base_url должен быть http://127.0.0.1:8000. Сначала проверьте GET /health (200), затем прочитайте /tasks и /stats и запишите baseline N/O/D.`}),(0,_.jsxs)(`p`,{children:[`Создайте контрольную задачу POST-телом `,(0,_.jsx)(`code`,{children:`{"title":"Control task","priority":1}`}),`. Для главной задачи используйте `,(0,_.jsx)(`code`,{children:`{"title":"Workflow task","priority":2}`}),`. Оба ответа должны иметь статус 201. Сохраните id и читайте главную по нему. Затем выполните PUT с `,(0,_.jsx)(`code`,{children:`{"title":"Reviewed workflow","priority":3,"is_done":true}`}),` (200), PATCH с `,(0,_.jsx)(`code`,{children:`{"priority":99}`}),` (422), PATCH с `,(0,_.jsx)(`code`,{children:`{"is_done":false}`}),` (200) и DELETE (204, пустое тело). После 422 перечитайте данные. После DELETE проверьте GET 404. Контрольную задачу и исходные записи оставьте.`]}),(0,_.jsx)(`p`,{children:`Stats меняются так же, как в автоматическом тесте: +2/+2/0 после POST, +2/+1/+1 после PUT, +2/+2/0 после PATCH false и +1/+1/0 после удаления главной. Сравните эти изменения с исходным baseline. Скрипты Postman для этой проверки не нужны.`}),(0,_.jsx)(`p`,{children:`Из корня StudyHub запустите pytest tests/test_workflow.py -q, чтобы проверить новый тест отдельно. Затем выполните pytest -q, чтобы проверить его вместе с остальными. В обоих случаях fixture использует временный файл. Если результат зависит от порядка тестов, проверьте восстановление app.state.planner. Этот тест и сценарий Postman станут входом занятия 60: там история повторится в чистой копии проекта.`})]}),(0,_.jsxs)(o,{number:`07`,title:`Что мы будем делать в практике`,children:[(0,_.jsx)(a,{children:`В практике три шага: добавить workflow-тест, пройти историю в Postman, затем запустить тест отдельно и вместе с набором. Используйте готовые маршруты, сервис и fixtures. Код приложения менять не нужно.`}),(0,_.jsx)(u,{variant:`connected`,items:[{title:`1. Напишем workflow-тест`,description:`Разделы 02-05 объясняют общий сервис, фактические id, повторный GET, stats и проверку после 422.`},{title:`2. Повторим историю в Postman`,description:`Раздел 06 объясняет запуск сервера, импорт коллекции и среды, baseline и тот же порядок запросов.`},{title:`3. Проверим изоляцию теста`,description:`Разделы 02 и 06 объясняют временный файл, отдельный запуск теста и запуск полного набора.`}]}),(0,_.jsx)(`p`,{children:`На входе уже есть отдельные проверки занятия 59. Здесь мы добавляем одну связанную историю и не повторяем CRUD. В тесте данные временные; в Postman сохраняем исходные записи и сравниваем stats с baseline.`}),(0,_.jsx)(`p`,{children:`Итог занятия: workflow-тест и пройденный сценарий Postman. Передайте их занятию 60: там вы повторите историю в чистой копии проекта, не реализуя CRUD заново.`})]})]})}export{v as Lesson59_1};